UPDATE TBL_BOND_FINANCING
BOND_CODE = #{bondCode}, BOND_NAME = #{bondName}, BOND_TYPE = #{bondType}, ISSUE_PRICE = #{issuePrice}, FACE_VALUE = #{faceValue}, COUPON_RATE = #{couponRate}, ISSUE_AMOUNT = #{issueAmount}, ACTUAL_AMOUNT = #{actualAmount}, ISSUE_START_DATE = #{issueStartDate}, ISSUE_END_DATE = #{issueEndDate}, MATURITY_DATE = #{maturityDate}, TERM = #{term}, PAYMENT_FREQUENCY = #{paymentFrequency}, LISTING_EXCHANGE = #{listingExchange}, UNDERWRITER = #{underwriter}, RATING_AGENCY = #{ratingAgency}, CREDIT_RATING = #{creditRating}, ISSUE_STATUS = #{issueStatus}, REMAINING_AMOUNT = #{remainingAmount}, TOTAL_INTEREST_PAID = #{totalInterestPaid}, CURRENCY = #{currency}, OPERATOR = #{operator}, REMARK = #{remark}, UPDATE_TIME = #{updateTime}, UPDATE_BY = #{updateBy},
WHERE BOND_ID = #{bondId}

UPDATE TBL_BOND_FINANCING
